begin;
select plan(27);
select has_table('public','import_job_batches','Batch receipts exist');
select has_table('public','import_rate_limits','Import limits exist');
select ok((select relrowsecurity from pg_class where oid='public.import_rate_limits'::regclass),'Limits use RLS');
select ok((select relrowsecurity from pg_class where oid='public.import_job_batches'::regclass),'Receipts use RLS');
select ok(not has_table_privilege('authenticated','public.import_rate_limits','delete'),'A caller cannot reset the ledger');
select ok(not has_table_privilege('authenticated','public.import_job_batches','update'),'Receipts cannot be updated');
select ok(not has_table_privilege('authenticated','public.import_job_batches','delete'),'Receipts cannot be deleted');
select ok(not has_function_privilege('authenticated','private.advance_import_progress()','execute'),'No direct privileged progress access');
select ok(not has_function_privilege('anon','private.advance_import_progress()','execute'),'No anonymous privileged progress access');
select is((select prosecdef from pg_proc where oid='public.begin_import_job(uuid,uuid,uuid,text,text,integer,jsonb)'::regprocedure),false,'Begin uses caller RLS');
select is((select prosecdef from pg_proc where oid='public.commit_import_batch(uuid,integer,jsonb,boolean)'::regprocedure),false,'Commit uses caller RLS');
select is((select prosecdef from pg_proc where oid='public.preview_import_duplicates(uuid,jsonb)'::regprocedure),false,'Preview uses caller RLS');
select is((select prosecdef from pg_proc where oid='private.advance_import_progress()'::regprocedure),true,'Protected metadata uses the private trigger');

insert into auth.users(id) values('a11ce000-0000-4000-8000-000000000001');
insert into public.profiles(id) values('a11ce000-0000-4000-8000-000000000001');
set local role authenticated;
set local request.jwt.claims to '{"sub":"a11ce000-0000-4000-8000-000000000001","role":"authenticated"}';
select lives_ok($$insert into public.import_rate_limits(owner_id,requested_rows,attempts,claimed_rows,window_date,requested_at)
  values('a11ce000-0000-4000-8000-000000000001',10,0,0,'1900-01-01','1900-01-01')$$,'Caller-supplied counters and clock are replaced');
select is((select attempts from public.import_rate_limits),1,'First attempt derives one');
select is((select claimed_rows from public.import_rate_limits),10,'Claimed rows are derived');
select is((select window_date from public.import_rate_limits),(clock_timestamp() at time zone 'UTC')::date,'Window uses server UTC');
select ok((select requested_at > clock_timestamp() - interval '5 seconds' from public.import_rate_limits),'Timestamp uses server clock');
select throws_ok($$update public.import_rate_limits set requested_rows=20,requested_at='1900-01-01'$$,'PT429','import cooldown','Backdating cannot bypass cooldown');
select pg_sleep(2.1);
select lives_ok($$update public.import_rate_limits set requested_rows=20,attempts=0,claimed_rows=0,window_date='1900-01-01',requested_at='1900-01-01'$$,'Update after cooldown succeeds');
select is((select attempts from public.import_rate_limits),2,'Forged zero cannot reset attempts');
select is((select claimed_rows from public.import_rate_limits),30,'Forged zero cannot reset claimed rows');
select is((select window_date from public.import_rate_limits),(clock_timestamp() at time zone 'UTC')::date,'Forged date cannot reset the daily window');
select ok(not has_function_privilege('authenticated','public.guard_import_rate_limit()','execute'),'Guard is trigger-only');
create temporary table synthetic_import_trigger_probe(id integer);
select throws_ok($$create trigger synthetic_probe after insert on synthetic_import_trigger_probe for each row execute function private.advance_import_progress()$$,'42501',null,'Caller cannot bind the private trigger to another table');
select throws_ok($$insert into public.import_rate_limits(owner_id,requested_rows) values('b0b0b000-0000-4000-8000-000000000002',10)$$,'42501',null,'Caller cannot charge another owner');
select throws_ok($$select private.advance_import_progress()$$,'42501',null,'Caller cannot invoke the privileged helper');
select * from finish();
rollback;
